async function freeHttp(self, url, opts = {}) {
  const start = Date.now();
  try {
    const req = {
      method: opts.method || 'GET',
      url,
      headers: {
        'User-Agent': FREE_AUDIT_UA,
        Accept: opts.accept || 'text/html,application/json,*/*',
