    };
    if (opts.body != null) req.body = opts.body;
    const data = await self.helpers.httpRequest(req);
    return { ok: true, data, ms: Date.now() - start };
  } catch (err) {
    return { ok: false, error: err.message, ms: Date.now() - start };
